//   TypeLambdas.d.ts
// ═══════════════════════════════════════════════════════
/**
 * TypeLambdas for JS built-in types (Array, Function).
 *
 * All per-data-type and transformer TypeLambdas now live in their own
 * files under ./data/ and ./data/transformers/. This file exists solely
 * for built-in JS types that do not have a dedicated data-file module.
 *
 * Ownership map:
 *   Maybe       → ./data/Maybe.d.ts
 *   Either      → ./data/Either.d.ts
 *   Task        → ./data/Task.d.ts
 *   Validation  → ./data/Validation.d.ts
 *   Reader      → ./data/Reader.d.ts
 *   Writer      → ./data/Writer.d.ts
 *   State       → ./data/State.d.ts
 *   Free        → ./data/Free.d.ts
 *   StateT(M)   → ./data/transformers/StateT.d.ts
 *   EitherT(M)  → ./data/transformers/EitherT.d.ts
 *   ReaderT(M)  → ./data/transformers/ReaderT.d.ts
 *   WriterT(M)  → ./data/transformers/WriterT.d.ts
 */

export interface ArrayTypeLambda extends TypeLambda {
    readonly type: ReadonlyArray<this["Target"]>;
}

// Identity — traverse 에 넘겨 "그냥 매핑" 으로 쓰는 Applicative. 담는 모양은 { value }.
export interface IdentityTypeLambda extends TypeLambda {
    readonly type: { readonly value: this["Target"] };
}

// Const<r> — 담는 모양은 Identity 와 같은 { value } 지만 map 이 값을 버린다.
// 목표 타입이 r 로 고정되므로 Target 을 쓰지 않는다.
export interface ConstTypeLambda extends TypeLambda {
    readonly type: { readonly value: unknown };
}

export interface FunctionTypeLambda extends TypeLambda {
    readonly type: (a: this["In"]) => this["Target"];
}

// ═══════════════════════════════════════════════════════
//   data/Identity.d.ts
// ═══════════════════════════════════════════════════════
/**
 * Identity — 값을 그대로 나르는 상자.
 *
 * `traverse` 에 넘기면 "그냥 매핑" 이 되고, optics 의 `over` 가 그렇게 씁니다.
 * 등록된 인스턴스: Functor / Apply / Applicative / Extend / Comonad (키 `'identity'`).
 *
 * 한때 `{ value }` 객체 리터럴이었습니다. 지금은 클래스입니다 —
 * docs/internals.md#identity-const
 */

export declare class Identity<A> {
    readonly value: A;
    readonly _typeName: "Identity";
    private constructor(value: A);
    map<B>(f: (a: A) => B): Identity<B>;
    chain<B>(f: (a: A) => Identity<B>): Identity<B>;
    extend<B>(f: (w: Identity<A>) => B): Identity<B>;
    extract(): A;
    /** 생성자는 비공개다 — 값을 넣는 문은 이것뿐이다. */
    static of<A>(value: A): Identity<A>;
    /** 심볼을 본다. `_typeName` 문자열만 베낀 객체는 여기서 걸린다. */
    static isIdentity(x: unknown): x is Identity<unknown>;
}

export type { IdentityTypeLambda };

// ═══════════════════════════════════════════════════════
//   data/Maybe.d.ts
// ═══════════════════════════════════════════════════════
/**
 * Maybe — optional value carrier.
 *
 * Owns: the `Maybe<A>` interface, `Just<A>` / `Nothing` narrow subtypes,
 * `MaybeTypeLambda`, the runtime `const Maybe` namespace, and the runtime
 * key `'maybe'` registered on every type-class `*Instances` registry.
 *
 * Deferred (added in follow-ups):
 *   traverse, chainRec, pipeK, composeK, toEither, Maybe.pipe,
 *   Semigroup.Maybe, Monoid.Maybe
 */

// ── Type ─────────────────────────────────────────────────────────────
export interface Maybe<A> {
    readonly _typeName: "Maybe";
    isJust(): this is Just<A>;
    isNothing(): this is Nothing;
    map<B>(f: (a: A) => B): Maybe<B>;
    chain<B>(f: (a: A) => Maybe<B>): Maybe<B>;
}

export interface Just<A> extends Maybe<A> {
    readonly value: A;
}

export interface Nothing extends Maybe<never> {}

// ── TypeLambda ───────────────────────────────────────────────────────
export interface MaybeTypeLambda extends TypeLambda {
    readonly type: Maybe<this["Target"]>;
}

// ── Value namespace (merges with the interface via declaration merging)
export declare const Maybe: {
    // Constructors
    readonly Just: <A>(a: A) => Just<A>;
    readonly Nothing: () => Nothing;
    readonly of: <A>(a: A) => Maybe<A>;

    // Predicates / type guards
    readonly isMaybe: (x: unknown) => x is Maybe<unknown>;
    readonly isJust: <A>(x: Maybe<A>) => x is Just<A>;
    readonly isNothing: <A>(x: Maybe<A>) => x is Nothing;

    // Transformations
    readonly fromNullable: <A>(x: A | null | undefined) => Maybe<NonNullable<A>>;
    readonly fold: <A, B>(
        onNothing: () => B,
        onJust: (a: A) => B,
        m: Maybe<A>
    ) => B;
    // Runtime: runCatch(() => Just(f()), Nothing) — thunk throws → Nothing.
    readonly catch: <A>(thunk: () => A) => Maybe<A>;

    // Static Land methods (wired at runtime from Functor.lookup('maybe').map etc.)
    readonly map: <A, B>(f: (a: A) => B, m: Maybe<A>) => Maybe<B>;
    readonly ap: <A, B>(
        mf: Maybe<(a: A) => B>,
        ma: Maybe<A>
    ) => Maybe<B>;
    readonly chain: <A, B>(
        f: (a: A) => Maybe<B>,
        m: Maybe<A>
    ) => Maybe<B>;
    readonly alt: <A>(ma: Maybe<A>, mb: Maybe<A>) => Maybe<A>;
    readonly zero: <A = never>() => Maybe<A>;
    readonly filter: {
        <A, B extends A>(pred: (a: A) => a is B, m: Maybe<A>): Maybe<B>;
        <A>(pred: (a: A) => boolean, m: Maybe<A>): Maybe<A>;
    };
    readonly reduce: <A, B>(
        f: (acc: B, a: A) => B,
        init: B,
        m: Maybe<A>
    ) => B;

    // Lifts an N-ary plain function into Maybe — liftA_n form.
    // `Maybe.lift(f)` returns a function that expects N Maybe-wrapped args
    // and returns a Maybe of the combined result (via `.ap` under the hood).
    // Runtime wraps the inner call in runCatch: if applying `f` throws or an
    // arg isn't a Maybe instance, the result falls back to `Maybe.Nothing()`.
    readonly lift: <Args extends readonly unknown[], R>(
        f: (...args: Args) => R
    ) => (
        ...wrapped: { [K in keyof Args]: Maybe<Args[K]> }
    ) => Maybe<R>;

    // ChainRec — stack-safe monadic recursion.
    readonly chainRec: <A, B>(
        f: (
            next: (a: A) => ChainRecStep<A, B>,
            done: (b: B) => ChainRecStep<A, B>,
            input: A
        ) => Maybe<ChainRecStep<A, B>>,
        init: A
    ) => Maybe<B>;

    // Traverse — distribute Maybe through an Applicative G. Slot
    // parameters of G are fixed at `never` (the common case); traversals
    // that need non-trivial G slots (e.g. Either<E, _> as the Applicative
    // with a custom E) should call via `Traversable.lookup('maybe').traverse`.
    //
    // Inference caveat: `B` is inferred through a conditional `Kind` type,
    // which TS sometimes fails to resolve when `G` is also being inferred.
    // Pass explicit type parameters when that happens:
    //   Maybe.traverse<TaskTypeLambda, A, B>(applicative, f, m)
    readonly traverse: <G extends TypeLambda, A, B>(
        applicative: Applicative<G>,
        f: (a: A) => Kind<G, never, never, never, B>,
        m: Maybe<A>
    ) => Kind<G, never, never, never, Maybe<B>>;

    // Kleisli composition (left-to-right). Overloads up to 4 args.
    readonly pipeK: {
        <A, B>(f1: (a: A) => Maybe<B>): (a: A) => Maybe<B>;
        <A, B, C>(
            f1: (a: A) => Maybe<B>,
            f2: (b: B) => Maybe<C>
        ): (a: A) => Maybe<C>;
        <A, B, C, D>(
            f1: (a: A) => Maybe<B>,
            f2: (b: B) => Maybe<C>,
            f3: (c: C) => Maybe<D>
        ): (a: A) => Maybe<D>;
        <A, B, C, D, E>(
            f1: (a: A) => Maybe<B>,
            f2: (b: B) => Maybe<C>,
            f3: (c: C) => Maybe<D>,
            f4: (d: D) => Maybe<E>
        ): (a: A) => Maybe<E>;
    };
    readonly composeK: {
        <A, B>(f1: (a: A) => Maybe<B>): (a: A) => Maybe<B>;
        <A, B, C>(
            f2: (b: B) => Maybe<C>,
            f1: (a: A) => Maybe<B>
        ): (a: A) => Maybe<C>;
        <A, B, C, D>(
            f3: (c: C) => Maybe<D>,
            f2: (b: B) => Maybe<C>,
            f1: (a: A) => Maybe<B>
        ): (a: A) => Maybe<D>;
        <A, B, C, D, E>(
            f4: (d: D) => Maybe<E>,
            f3: (c: C) => Maybe<D>,
            f2: (b: B) => Maybe<C>,
            f1: (a: A) => Maybe<B>
        ): (a: A) => Maybe<E>;
    };

    // Conversion helpers.
    readonly toEither: <E, A>(defaultLeft: E, m: Maybe<A>) => Either<E, A>;

    // Pipe — chains Maybe-returning functions but the functions receive
    // the Maybe itself (not the inner value). Breaks on Nothing.
    readonly pipe: {
        <A, B>(m: Maybe<A>, f1: (m: Maybe<A>) => Maybe<B>): Maybe<B>;
        <A, B, C>(
            m: Maybe<A>,
            f1: (m: Maybe<A>) => Maybe<B>,
            f2: (m: Maybe<B>) => Maybe<C>
        ): Maybe<C>;
        <A, B, C, D>(
            m: Maybe<A>,
            f1: (m: Maybe<A>) => Maybe<B>,
            f2: (m: Maybe<B>) => Maybe<C>,
            f3: (m: Maybe<C>) => Maybe<D>
        ): Maybe<D>;
    };

};

// ── 제약이 붙은 Maybe 인스턴스는 타입 클래스 쪽에 산다 ─────────────────
// Inner type A needs a Semigroup for value-level concat on Just/Just;
// Nothing is the identity, so Monoid.Maybe takes a Semigroup (not a Monoid).
// Equality/order need the inner instance. Nothing equals only Nothing;
// for Ord, Nothing is the least value (matches fp-ts getOrd).
interface SemigroupStatic {
    readonly Maybe: {
        <K extends keyof SemigroupInstances>(innerSG: K): Semigroup<Maybe<SemigroupInstances[K]>>;
        <A>(innerSG: Semigroup<A>): Semigroup<Maybe<A>>;
    };
}
interface MonoidStatic {
    readonly Maybe: {
        <K extends keyof SemigroupInstances>(innerSG: K): Monoid<Maybe<SemigroupInstances[K]>>;
        <A>(innerSG: Semigroup<A>): Monoid<Maybe<A>>;
    };
}
interface SetoidStatic {
    readonly Maybe: {
        <K extends keyof SetoidInstances>(inner: K): Setoid<Maybe<SetoidInstances[K]>>;
        <A>(inner: Setoid<A>): Setoid<Maybe<A>>;
    };
}
interface OrdStatic {
    readonly Maybe: {
        <K extends keyof OrdInstances>(inner: K): Ord<Maybe<OrdInstances[K]>>;
        <A>(inner: Ord<A>): Ord<Maybe<A>>;
    };
}

// ── Register 'maybe' on every type-class runtime registry ────────────
interface FunctorInstances     { readonly maybe: MaybeTypeLambda }
interface ApplyInstances       { readonly maybe: MaybeTypeLambda }
interface ApplicativeInstances { readonly maybe: MaybeTypeLambda }
interface ChainInstances       { readonly maybe: MaybeTypeLambda }
interface ChainRecInstances    { readonly maybe: MaybeTypeLambda }
interface MonadInstances       { readonly maybe: MaybeTypeLambda }
interface AltInstances         { readonly maybe: MaybeTypeLambda }
interface PlusInstances        { readonly maybe: MaybeTypeLambda }
interface AlternativeInstances { readonly maybe: MaybeTypeLambda }
interface FoldableInstances    { readonly maybe: MaybeTypeLambda }
interface TraversableInstances { readonly maybe: MaybeTypeLambda }
interface FilterableInstances  { readonly maybe: MaybeTypeLambda }

// ═══════════════════════════════════════════════════════
//   data/Either.d.ts
// ═══════════════════════════════════════════════════════
/**
 * Either — disjoint sum carrying success (Right) or failure (Left).
 *
 * Slot assignment:
 *   Out2   — E (Left / error channel)
 *   Target — A (Right / success)
 *
 * Owns: the `Either<E, A>` interface, `Left<E>` / `Right<A>` narrow
 * subtypes, `EitherTypeLambda`, the runtime `const Either` namespace, and
 * the runtime key `'either'` registered on the type classes Either
 * implements at runtime (Functor / Apply / Applicative / Alt / Chain /
 * Monad / Foldable / Traversable — not Plus, not Alternative).
 *
 * Deferred (added in follow-ups):
 *   traverse, chainRec, pipeK, composeK, bimap (needs Bifunctor class),
 *   Either.pipe, Semigroup.Either, Either.Monoid, Semigroupoid / Category
 */

// ── Type ─────────────────────────────────────────────────────────────
export interface Either<E, A> {
    readonly _typeName: "Either";
    isLeft(): this is Left<E>;
    isRight(): this is Right<A>;
    map<B>(f: (a: A) => B): Either<E, B>;
    chain<B>(f: (a: A) => Either<E, B>): Either<E, B>;
}

export interface Left<E> extends Either<E, never> {
    readonly value: E;
}

export interface Right<A> extends Either<never, A> {
    readonly value: A;
}

// ── TypeLambda ───────────────────────────────────────────────────────
export interface EitherTypeLambda extends TypeLambda {
    readonly type: Either<this["Out2"], this["Target"]>;
}

// ── Value namespace ──────────────────────────────────────────────────
export declare const Either: {
    // Constructors
    readonly Left: <E>(e: E) => Left<E>;
    readonly Right: <A>(a: A) => Right<A>;
    readonly of: <A>(a: A) => Either<never, A>;

    // Predicates / type guards
    readonly isEither: (x: unknown) => x is Either<unknown, unknown>;
    readonly isLeft: <E, A>(x: Either<E, A>) => x is Left<E>;
    readonly isRight: <E, A>(x: Either<E, A>) => x is Right<A>;

    // Transformations
    readonly fromNullable: <A>(
        x: A | null | undefined
    ) => Either<null, NonNullable<A>>;
    readonly fold: <E, A, B>(
        onLeft: (e: E) => B,
        onRight: (a: A) => B,
        e: Either<E, A>
    ) => B;
    // Runtime: runCatch(() => Right(f()), Left) — thunk throws → Left(error).
    // Caught error is typed `unknown` (TS 4.4+ convention).
    readonly catch: <A>(thunk: () => A) => Either<unknown, A>;

    // Conversions
    readonly toMaybe: <E, A>(e: Either<E, A>) => Maybe<A>;

    // Static Land methods
    readonly map: <E, A, B>(
        f: (a: A) => B,
        e: Either<E, A>
    ) => Either<E, B>;
    readonly ap: <E, A, B>(
        ef: Either<E, (a: A) => B>,
        ea: Either<E, A>
    ) => Either<E, B>;
    readonly chain: <E, A, B>(
        f: (a: A) => Either<E, B>,
        e: Either<E, A>
    ) => Either<E, B>;
    readonly alt: <E, A>(
        a: Either<E, A>,
        b: Either<E, A>
    ) => Either<E, A>;

    // Filter: runtime default for onFalse is `identity`, which folds A back
    // into the Left channel. Two overload pairs reflect both usages.
    readonly filter: {
        <E, A, B extends A>(
            pred: (a: A) => a is B,
            e: Either<E, A>,
            onFalse: (a: A) => E
        ): Either<E, B>;
        <E, A>(
            pred: (a: A) => boolean,
            e: Either<E, A>,
            onFalse: (a: A) => E
        ): Either<E, A>;
        <E, A, B extends A>(
            pred: (a: A) => a is B,
            e: Either<E, A>
        ): Either<E | A, B>;
        <E, A>(
            pred: (a: A) => boolean,
            e: Either<E, A>
        ): Either<E | A, A>;
    };

    readonly reduce: <E, A, B>(
        f: (acc: B, a: A) => B,
        init: B,
        e: Either<E, A>
    ) => B;

    // Lifts an N-ary plain function into Either — liftA_n form.
    // Takes N Either-wrapped args of the same E and returns Either<E, R>.
    // Runtime runCatch wrapper: on throw, result falls back to
    // `Either.Left(error)` (error typed `unknown`).
    readonly lift: <Args extends readonly unknown[], R>(
        f: (...args: Args) => R
    ) => <E = unknown>(
        ...wrapped: { [K in keyof Args]: Either<E, Args[K]> }
    ) => Either<E, R>;

    // Bifunctor.bimap: transform both channels simultaneously.
    readonly bimap: <E1, E2, A, B>(
        f: (e: E1) => E2,
        g: (a: A) => B,
        e: Either<E1, A>
    ) => Either<E2, B>;

    readonly chainRec: <E, A, B>(
        f: (
            next: (a: A) => ChainRecStep<A, B>,
            done: (b: B) => ChainRecStep<A, B>,
            input: A
        ) => Either<E, ChainRecStep<A, B>>,
        init: A
    ) => Either<E, B>;

    // Traverse — G's slot parameters pinned to `never` for clean
    // inference; see Maybe.traverse note for the full-signature escape.
    readonly traverse: <G extends TypeLambda, E, A, B>(
        applicative: Applicative<G>,
        f: (a: A) => Kind<G, never, never, never, B>,
        e: Either<E, A>
    ) => Kind<G, never, never, never, Either<E, B>>;

    readonly pipeK: {
        <E, A, B>(f1: (a: A) => Either<E, B>): (a: A) => Either<E, B>;
        <E, A, B, C>(
            f1: (a: A) => Either<E, B>,
            f2: (b: B) => Either<E, C>
        ): (a: A) => Either<E, C>;
        <E, A, B, C, D>(
            f1: (a: A) => Either<E, B>,
            f2: (b: B) => Either<E, C>,
            f3: (c: C) => Either<E, D>
        ): (a: A) => Either<E, D>;
        <E, A, B, C, D, F>(
            f1: (a: A) => Either<E, B>,
            f2: (b: B) => Either<E, C>,
            f3: (c: C) => Either<E, D>,
            f4: (d: D) => Either<E, F>
        ): (a: A) => Either<E, F>;
    };
    readonly composeK: {
        <E, A, B>(f1: (a: A) => Either<E, B>): (a: A) => Either<E, B>;
        <E, A, B, C>(
            f2: (b: B) => Either<E, C>,
            f1: (a: A) => Either<E, B>
        ): (a: A) => Either<E, C>;
        <E, A, B, C, D>(
            f3: (c: C) => Either<E, D>,
            f2: (b: B) => Either<E, C>,
            f1: (a: A) => Either<E, B>
        ): (a: A) => Either<E, D>;
    };

    // Pipe — accepts functions taking the whole Either. Breaks on Left.
    readonly pipe: {
        <E, A, B>(
            e: Either<E, A>,
            f1: (e: Either<E, A>) => Either<E, B>
        ): Either<E, B>;
        <E, A, B, C>(
            e: Either<E, A>,
            f1: (e: Either<E, A>) => Either<E, B>,
            f2: (e: Either<E, B>) => Either<E, C>
        ): Either<E, C>;
        <E, A, B, C, D>(
            e: Either<E, A>,
            f1: (e: Either<E, A>) => Either<E, B>,
            f2: (e: Either<E, B>) => Either<E, C>,
            f3: (e: Either<E, C>) => Either<E, D>
        ): Either<E, D>;
    };

};

// ── 제약이 붙은 Either 인스턴스는 타입 클래스 쪽에 산다 ────────────────
// Semigroup concats both channels (Left/Left, Right/Right), so it needs
// two inner Semigroups — the runtime raises on a single argument.
// Either has two slots with different types, so equality takes two
// instances (Haskell: (Eq a, Eq b); fp-ts: getEq(EL, EA)). There is
// deliberately no Ord.Either — Left-before-Right has no canonical
// justification; fp-ts leaves it out of core too.
interface SemigroupStatic {
    readonly Either: {
        <KL extends keyof SemigroupInstances, KR extends keyof SemigroupInstances>(
            left: KL, right: KR
        ): Semigroup<Either<SemigroupInstances[KL], SemigroupInstances[KR]>>;
        <E, A>(left: Semigroup<E> | string, right: Semigroup<A> | string): Semigroup<Either<E, A>>;
    };
}
interface SetoidStatic {
    readonly Either: {
        <KL extends keyof SetoidInstances, KR extends keyof SetoidInstances>(
            left: KL, right: KR
        ): Setoid<Either<SetoidInstances[KL], SetoidInstances[KR]>>;
        <E, A>(left: Setoid<E> | string, right: Setoid<A> | string): Setoid<Either<E, A>>;
    };
}

// ── Register 'either' on the type-class runtime registries ───────────
// Either runtime has: Functor, Apply, Applicative, Alt, Chain, ChainRec,
// Monad, Foldable, Traversable, Filterable, Bifunctor.
// NOT Plus/Alternative (no zero).
interface FunctorInstances     { readonly either: EitherTypeLambda }
interface ApplyInstances       { readonly either: EitherTypeLambda }
interface ApplicativeInstances { readonly either: EitherTypeLambda }
interface AltInstances         { readonly either: EitherTypeLambda }
interface ChainInstances       { readonly either: EitherTypeLambda }
interface ChainRecInstances    { readonly either: EitherTypeLambda }
interface MonadInstances       { readonly either: EitherTypeLambda }
interface MonadErrorInstances  { readonly either: EitherTypeLambda }
interface FoldableInstances    { readonly either: EitherTypeLambda }
interface TraversableInstances { readonly either: EitherTypeLambda }
interface BifunctorInstances   { readonly either: EitherTypeLambda }

// ═══════════════════════════════════════════════════════
//   data/Task.d.ts
// ═══════════════════════════════════════════════════════
/**
 * Task — lazy async computation. Promise-like but deferred until `fork`.
 *
 * Slot assignment:
 *   Target — A (success channel)
 * Rejection channel is NOT typed (runtime accepts any thrown value);
 * caught errors surface as `unknown` at the TS boundary.
 * For typed errors, compose with EitherT(Task).
 *
 * Owns: the `Task<A>` interface, `TaskTypeLambda`, the runtime `const Task`
 * namespace, and the runtime key `'task'` on the 6 type-class registries
 * Task implements (Functor / Apply / Applicative / Alt / Chain / Monad).
 *
 * Deferred (added in follow-ups):
 *   filter (needs Filterable class), chainRec, pipeK, composeK,
 *   Semigroupoid / Category
 */

// ── Type ─────────────────────────────────────────────────────────────
export interface Task<A> {
    readonly _typeName: "Task";
    // Execute the deferred computation. At-most-once settle guarded by
    // the runtime — multiple reject/resolve calls are no-ops.
    fork(
        onReject: (error: unknown) => void,
        onResolve: (a: A) => void
    ): void;
    map<B>(f: (a: A) => B): Task<B>;
    chain<B>(f: (a: A) => Task<B>): Task<B>;
    catchError(handler: (e: unknown) => Task<A>): Task<A>;
}

// ── TypeLambda ───────────────────────────────────────────────────────
export interface TaskTypeLambda extends TypeLambda {
    readonly type: Task<this["Target"]>;
}

// ── Value namespace ──────────────────────────────────────────────────
export declare const Task: {
    // Note: there is no `new Task(computation)` in the public TS surface.
    // Users construct via `Task.of` / `Task.rejected` / `Task.fromPromise`
    // or by composing existing Tasks. The class constructor exists in the
    // JS runtime but is treated as an implementation detail in TS.

    // Constructors
    readonly of: <A>(a: A) => Task<A>;
    readonly rejected: (e: unknown) => Task<never>;

    // Predicate
    readonly isTask: (x: unknown) => x is Task<unknown>;

    // Execute and fold — convenience alias for `task.fork(...)`.
    readonly fold: <A>(
        onRejected: (e: unknown) => void,
        onResolved: (a: A) => void,
        task: Task<A>
    ) => void;

    // Promise interop — `promiseFn` may return either a Promise or a raw
    // value. Thrown errors during the call become the rejection channel.
    readonly fromPromise: <Args extends readonly unknown[], T>(
        promiseFn: (...args: Args) => T | PromiseLike<T>
    ) => (...args: Args) => Task<Awaited<T>>;

    // Either interop — Right → resolved Task, Left → rejected Task.
    readonly fromEither: <E, A>(e: Either<E, A>) => Task<A>;

    // Parallel execution: `all` waits for every task, `race` picks first.
    readonly all: <T extends ReadonlyArray<Task<unknown>>>(
        tasks: T
    ) => Task<{
        -readonly [K in keyof T]: T[K] extends Task<infer U> ? U : never;
    }>;
    readonly race: <T extends ReadonlyArray<Task<unknown>>>(
        tasks: T
    ) => Task<T[number] extends Task<infer U> ? U : never>;

    // Error handling — hands rejection to `handler` which returns a fresh Task.
    readonly catchError: <A>(
        handler: (e: unknown) => Task<A>,
        task: Task<A>
    ) => Task<A>;

    // Static Land methods
    readonly map: <A, B>(f: (a: A) => B, t: Task<A>) => Task<B>;
    readonly ap: <A, B>(
        tf: Task<(a: A) => B>,
        ta: Task<A>
    ) => Task<B>;
    readonly chain: <A, B>(
        f: (a: A) => Task<B>,
        t: Task<A>
    ) => Task<B>;
    readonly alt: <A>(a: Task<A>, b: Task<A>) => Task<A>;

    // Lifts an N-ary plain function into Task — liftA_n form.
    // Takes N Task-wrapped args and returns Task<R>. Runtime runCatch
    // wrapper: on throw during lift application, result falls back to
    // `Task.rejected(error)`.
    readonly lift: <Args extends readonly unknown[], R>(
        f: (...args: Args) => R
    ) => (
        ...wrapped: { [K in keyof Args]: Task<Args[K]> }
    ) => Task<R>;

    // Filterable.filter: predicate-true keeps resolved value; false triggers
    // rejection with a library-chosen error. Typical usage is a type-guard.
    readonly filter: {
        <A, B extends A>(pred: (a: A) => a is B, t: Task<A>): Task<B>;
        <A>(pred: (a: A) => boolean, t: Task<A>): Task<A>;
    };

    readonly chainRec: <A, B>(
        f: (
            next: (a: A) => ChainRecStep<A, B>,
            done: (b: B) => ChainRecStep<A, B>,
            input: A
        ) => Task<ChainRecStep<A, B>>,
        init: A
    ) => Task<B>;

    readonly pipeK: {
        <A, B>(f1: (a: A) => Task<B>): (a: A) => Task<B>;
        <A, B, C>(
            f1: (a: A) => Task<B>,
            f2: (b: B) => Task<C>
        ): (a: A) => Task<C>;
        <A, B, C, D>(
            f1: (a: A) => Task<B>,
            f2: (b: B) => Task<C>,
            f3: (c: C) => Task<D>
        ): (a: A) => Task<D>;
        <A, B, C, D, E>(
            f1: (a: A) => Task<B>,
            f2: (b: B) => Task<C>,
            f3: (c: C) => Task<D>,
            f4: (d: D) => Task<E>
        ): (a: A) => Task<E>;
    };
    readonly composeK: {
        <A, B>(f1: (a: A) => Task<B>): (a: A) => Task<B>;
        <A, B, C>(
            f2: (b: B) => Task<C>,
            f1: (a: A) => Task<B>
        ): (a: A) => Task<C>;
        <A, B, C, D>(
            f3: (c: C) => Task<D>,
            f2: (b: B) => Task<C>,
            f1: (a: A) => Task<B>
        ): (a: A) => Task<D>;
    };
};

// ── Register 'task' on the type-class runtime registries ─────────────
// Task runtime has: Functor, Apply, Applicative, Alt, Chain, ChainRec,
// Monad, Filterable. Not Plus/Alternative (no zero); not Foldable/
// Traversable (async values cannot be folded without execution).
interface FunctorInstances     { readonly task: TaskTypeLambda }
interface ApplyInstances       { readonly task: TaskTypeLambda }
interface ApplicativeInstances { readonly task: TaskTypeLambda }
interface AltInstances         { readonly task: TaskTypeLambda }
interface ChainInstances       { readonly task: TaskTypeLambda }
interface ChainRecInstances    { readonly task: TaskTypeLambda }
interface MonadInstances       { readonly task: TaskTypeLambda }
interface MonadErrorInstances  { readonly task: TaskTypeLambda }

// ═══════════════════════════════════════════════════════
//   data/Validation.d.ts
// ═══════════════════════════════════════════════════════
/**
 * Validation — disjoint sum like Either, but errors accumulate via a
 * Semigroup on the Invalid channel, not short-circuit.
 *
 * Slot assignment:
 *   Out2   — E (Invalid errors)
 *   Target — A (Valid value)
 *
 * Key difference from Either: Validation is Apply/Applicative but NOT
 * Chain/Monad — chain couldn't preserve the accumulation semantics.
 *
 * Owns: the `Validation<E, A>` interface, `Valid<A>` / `Invalid<E>`
 * subtypes, `ValidationTypeLambda`, the runtime `const Validation`
 * namespace, and the key `'validation'` on Functor / Apply / Applicative
 * / Foldable registries.
 *
 * Deferred: bimap (needs Bifunctor class), Semigroupoid / Category
 */

// ── Type ─────────────────────────────────────────────────────────────
export interface Validation<E, A> {
    readonly _typeName: "Validation";
    isValid(): this is Valid<A>;
    isInvalid(): this is Invalid<E>;
    map<B>(f: (a: A) => B): Validation<E, B>;
    toEither(): Either<E, A>;
}

export interface Valid<A> extends Validation<never, A> {
    readonly value: A;
}

export interface Invalid<E> extends Validation<E, never> {
    readonly errors: E;
    // Runtime-held Monoid instance used for accumulation. Typed as
    // `unknown` until the Monoid type class is declared.
    readonly monoid: unknown;
}

// ── TypeLambda ───────────────────────────────────────────────────────
export interface ValidationTypeLambda extends TypeLambda {
    readonly type: Validation<this["Out2"], this["Target"]>;
}

// ── Value namespace ──────────────────────────────────────────────────
export declare const Validation: {
    // Constructors. `monoid` defaults to the array Monoid at runtime.
    readonly Valid: <A>(a: A) => Valid<A>;
    readonly Invalid: <E>(errors: E, monoid?: unknown) => Invalid<E>;
    readonly of: <A>(a: A) => Validation<never, A>;

    // Predicates / type guards
    readonly isValidation: (x: unknown) => x is Validation<unknown, unknown>;
    readonly isValid: <E, A>(v: Validation<E, A>) => v is Valid<A>;
    readonly isInvalid: <E, A>(v: Validation<E, A>) => v is Invalid<E>;

    // Conversions
    readonly fromEither: <E, A>(
        e: Either<E, A>,
        monoid?: unknown
    ) => Validation<E, A>;
    readonly fold: <E, A, B>(
        onInvalid: (errors: E) => B,
        onValid: (a: A) => B,
        v: Validation<E, A>
    ) => B;

    // Static Land methods. `ap` accumulates Invalid errors via the
    // runtime-held Monoid.
    readonly map: <E, A, B>(
        f: (a: A) => B,
        v: Validation<E, A>
    ) => Validation<E, B>;
    readonly ap: <E, A, B>(
        vf: Validation<E, (a: A) => B>,
        va: Validation<E, A>
    ) => Validation<E, B>;
    readonly bimap: <E1, E2, A, B>(
        f: (errors: E1) => E2,
        g: (a: A) => B,
        v: Validation<E1, A>
    ) => Validation<E2, B>;
    readonly reduce: <E, A, B>(
        f: (acc: B, a: A) => B,
        init: B,
        v: Validation<E, A>
    ) => B;

    // `collect` — runs N Either-valued validators in parallel against N args,
    // accumulates Left values into an array, then applies `f` to the values
    // if all validators succeeded. Overloads up to 4 validators.
    readonly collect: {
        <A1, B1, E>(
            v1: (a: A1) => Either<E, B1>
        ): <R>(
            f: (b1: B1) => R
        ) => (a1: A1) => Validation<E[], R>;
        <A1, A2, B1, B2, E>(
            v1: (a: A1) => Either<E, B1>,
            v2: (a: A2) => Either<E, B2>
        ): <R>(
            f: (b1: B1, b2: B2) => R
        ) => (a1: A1, a2: A2) => Validation<E[], R>;
        <A1, A2, A3, B1, B2, B3, E>(
            v1: (a: A1) => Either<E, B1>,
            v2: (a: A2) => Either<E, B2>,
            v3: (a: A3) => Either<E, B3>
        ): <R>(
            f: (b1: B1, b2: B2, b3: B3) => R
        ) => (a1: A1, a2: A2, a3: A3) => Validation<E[], R>;
        <A1, A2, A3, A4, B1, B2, B3, B4, E>(
            v1: (a: A1) => Either<E, B1>,
            v2: (a: A2) => Either<E, B2>,
            v3: (a: A3) => Either<E, B3>,
            v4: (a: A4) => Either<E, B4>
        ): <R>(
            f: (b1: B1, b2: B2, b3: B3, b4: B4) => R
        ) => (a1: A1, a2: A2, a3: A3, a4: A4) => Validation<E[], R>;
    };
};

// ── Register 'validation' on type-class registries ───────────────────
// Runtime: Functor, Apply, Applicative, Foldable, Bifunctor.
interface FunctorInstances     { readonly validation: ValidationTypeLambda }
interface ApplyInstances       { readonly validation: ValidationTypeLambda }
interface ApplicativeInstances { readonly validation: ValidationTypeLambda }
interface FoldableInstances    { readonly validation: ValidationTypeLambda }
interface BifunctorInstances   { readonly validation: ValidationTypeLambda }

